Please produce the Jac equivalent of the following TypeScript. Output only ```jac ... ```.
```ts
import { db } from '@/server/db/db';
import { link } from '@/server/db/schema';
import { eq } from 'drizzle-orm';
import type { MetadataRoute } from 'next';

const BASE_URL = 'https://www.openbio.app';

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const staticRoutes: MetadataRoute.Sitemap = [
    '/',
    '/explore',
    '/legal/privacy',
    '/legal/terms',
    '/claim-link',
    '/app/sign-in',
    '/app/sign-up',
  ].map((route) => ({
    url: `${BASE_URL}${route}`,
    lastModified: new Date(),
    changeFrequency: 'weekly',
    priority: route === '/' ? 1 : 0.5,
  }));

  const profiles = await db
    .select({
      link: link.link,
      updatedAt: link.updatedAt,
    })
    .from(link)
    .where(eq(link.isPublic, true));

  const profileRoutes: MetadataRoute.Sitemap = profiles.map((p) => ({
    url: `${BASE_URL}/${p.link}`,
    lastModified: p.updatedAt ?? new Date(),
    changeFrequency: 'daily',
    priority: 0.8,
  }));

  return [...staticRoutes, ...profileRoutes];
}
```

```jac
import from "@/server/db/db" { db }
import from "@/server/db/schema" { link }
import from "drizzle-orm" { eq }

glob BASE_URL: str = "https://www.openbio.app";

async def:pub sitemap() -> list[dict[str, object]] {
    staticRoutes = ["/", "/explore", "/legal/privacy", "/legal/terms", "/claim-link", "/app/sign-in", "/app/sign-up"];
    staticRouteEntries = [{"url": f"{BASE_URL}{route}", "lastModified": "", "changeFrequency": "weekly", "priority": 1.0 if route == "/" else 0.5} for route in staticRoutes];
    profiles = await db.select({"link": link.link, "updatedAt": link.updatedAt}).from(link).where(eq(link.isPublic, True));
    profileRoutes = [{"url": f"{BASE_URL}/{p["link"]}", "lastModified": p["updatedAt"] if p["updatedAt"] else "", "changeFrequency": "daily", "priority": 0.8} for p in profiles];
    return staticRouteEntries + profileRoutes;
}
```

