import from "@/app/(home)/data-table/schema" { userExpensesResponseSchema }

glob API_BASE_URL = "/api";

obj FetchUserExpensesParams {
    has userId: int,
        from_date: str = "",
        to_date: str = "",
        page: int = 1,
        limit: int = 10;
}

async def:pub fetchUserExpenses(params: FetchUserExpensesParams) -> object {
    query_parts: list[str] = [];
    if params.from_date {
        query_parts.append("from_date=" + params.from_date);
    }
    if params.to_date {
        query_parts.append("to_date=" + params.to_date);
    }
    query_parts.append("page=" + str(params.page));
    query_parts.append("limit=" + str(params.limit));
    query = "&".join(query_parts);
    response = await fetch(
        API_BASE_URL + "/users/" + str(params.userId) + "/expenses?" + query
    );
    if not response.ok {
        raise Exception("Failed to fetch user expenses: " + response.statusText);
    }
    data = await response.json();
    return userExpensesResponseSchema.parse(data);
}
