    results: list[User] = [];
    i = 0;
    while i < len(numericIds) {
        batchIds = numericIds[i:i + BATCH_SIZE];
        query_parts: list[str] = [];
        for id in batchIds {
            query_parts.append("id=" + str(id));
        }
        query_parts.append("limit=1000");
        query = "&".join(query_parts);
        response = await fetch(API_BASE_URL + "/users?" + query);
        if not response.ok {
            raise Exception("Failed to fetch users: " + response.statusText);
        }
        data = await response.json();
        parsed = usersResponseSchema.parse(data) as UsersListResponse;
        results = results + parsed.data;
        i = i + BATCH_SIZE;
    }
    return results;
