  // locate definition
  const result = await db.query.definitions.findFirst({
    orderBy: desc(definitions.upvotes),
    where: and(
      eq(definitions.status, 'approved'),
      eq(definitions.term, sql`${term} COLLATE NOCASE`)
    ),
    with: {
      user: {
        columns: {
          name: true
        }
      }
    }
