obj ApiEndpointProbe {
    has endpoint: str,
        ok: bool = False,
        latencyMs: float = 0.0;
}

def latencyTone(latencyMs: float) -> str {
    if latencyMs <= 500 {
        return "text-emerald-600 dark:text-emerald-400";
    }
    if latencyMs <= 1500 {
        return "text-amber-600 dark:text-amber-400";
    }
    return "text-orange-600 dark:text-orange-400";
}

def EndpointDisplay(
    endpoint: str,
    probe: ApiEndpointProbe | None = None,
    isDiscovering: bool = False,
    isRefreshingEndpoints: bool = False,
    compact: bool = False
) -> JsxElement {
    if isDiscovering or isRefreshingEndpoints {
        return <LoaderCircleIcon className="size-4 animate-spin" />;
    }
    if probe is None {
        return <span>{formatEndpoint(endpoint)}</span>;
    }
    if probe.ok {
        return <span className={cn("inline-flex items-center gap-1", latencyTone(probe.latencyMs))}>
            <CheckCircle2Icon className="size-4" />
            {formatEndpoint(endpoint)}
            {not compact and <span>{f"{int(probe.latencyMs)} ms"}</span>}
        </span>;
    }
    return <span className="inline-flex items-center gap-1">
        <XCircleIcon className="size-4" />
        {formatEndpoint(endpoint)}
    </span>;
}

def:pub ApiEndpointSection(
    endpoint: str,
