def:pub FloatingPill() -> JsxElement {
    has active_page: int = 2;
    total_pages = 5;

    def handle_prev(e: MouseEvent) {
        e.preventDefault();
        active_page = max(1, active_page - 1);
    }

    def handle_next(e: MouseEvent) {
