        active_page = min(total_pages, active_page + 1);
    }

    def handle_select(page: int) -> Callable[[MouseEvent], None] {
        return lambda (e: MouseEvent) {
            e.preventDefault();
            active_page = page;
        };
    }

    <Pagination>
        <PaginationContent className="bg-background/80 border p-1 rounded-full transition-all">
            <PaginationItem>
                <PaginationPrevious
                    href="#"
                    onClick={handle_prev}
                    className="rounded-full hover:bg-muted"
                />
            </PaginationItem>
            <div className="relative flex items-center mx-1">
                {for i in range(total_pages) {
                    page = i + 1;
                    is_active = active_page == page;
                    <PaginationItem key={page} className="relative">
                        <PaginationLink
                            href="#"
                            isActive={is_active}
                            onClick={handle_select(page)}
                            className={cn(
                                "relative z-10 w-9 h-9 rounded-full border-0 transition-colors uppercase text-xs font-bold tracking-tighter",
                                "bg-transparent text-primary-foreground hover:bg-transparent hover:text-primary-foreground" if is_active else "text-muted-foreground hover:text-foreground hover:bg-muted"
                            )}
                        >
                            {page}
                        </PaginationLink>
                        {if is_active {
                            <motion.div
                                layoutId="pill-active"
                                className="absolute inset-0 bg-primary rounded-full shadow-md"
                                transition={{"type": "spring", "bounce": 0.2, "duration": 0.6}}
                            />
                        }}
                    </PaginationItem>
                }}
            </div>
            <PaginationItem>
                <PaginationNext
                    href="#"
                    onClick={handle_next}
                    className="rounded-full hover:bg-muted transition-transform active:scale-95"
                />
            </PaginationItem>
        </PaginationContent>
    </Pagination>
}
