    can with [selected] entry {
        if len(selected) == len(items) {
            checked = True;
        } elif len(selected) > 0 {
            checked = "indeterminate";
        } else {
            checked = False;
        }
    }

    def handle_checked_change(value: bool | str) {
        checked = value;
        if value == True {
            selected = [item for item in items];
        } elif value == False {
            selected = [];
        }
    }

    def handle_item_change(label: str, value: bool) {
        if value {
            selected = selected + [label];
        } else {
            selected = [item for item in selected if item != label];
        }
    }

    <div className="flex flex-col gap-4">
        <div className="flex items-center gap-2">
            <Checkbox id="Brands" checked={checked} onCheckedChange={handle_checked_change} />
            <Label htmlFor="Brands">Brands</Label>
        </div>
        <div className="flex flex-col gap-2 pl-6">
            {for label in items {
                <div key={label} className="flex items-center gap-2">
                    <Checkbox
                        id={label}
                        checked={label in selected}
                        onCheckedChange={lambda (value: bool) { handle_item_change(label, value); }}
                    />
                    <Label htmlFor={label} className="text-muted-foreground">
                        label;
                    </Label>
                </div>
            }}
        </div>
    </div>
}
