import json;

glob STORAGE_KEY = "inklish:settings:v1";

obj Settings {
    has aiHighlights: bool = True;
    has submissionHighlights: bool = True;
    has liveCoach: bool = True;
}

glob defaults: Settings = Settings();

def load() -> Settings {
    try {
        raw = localStorage.getItem(STORAGE_KEY);
        if not raw {
            return defaults;
        }
        overlay = json.loads(raw) as dict[str, bool];
        return Settings(
            aiHighlights=overlay.get("aiHighlights", defaults.aiHighlights),
            submissionHighlights=overlay.get("submissionHighlights", defaults.submissionHighlights),
            liveCoach=overlay.get("liveCoach", defaults.liveCoach),
        );
    } except Exception {
        return defaults;
    }
}

glob settings: Settings = load();

def updateSettings(patch: dict[str, bool]) {
    settings = Settings(
        aiHighlights=patch.get("aiHighlights", settings.aiHighlights),
        submissionHighlights=patch.get("submissionHighlights", settings.submissionHighlights),
        liveCoach=patch.get("liveCoach", settings.liveCoach),
    );
    try {
        localStorage.setItem(
            STORAGE_KEY,
            json.dumps(
                {
                    "aiHighlights": settings.aiHighlights,
                    "submissionHighlights": settings.submissionHighlights,
                    "liveCoach": settings.liveCoach,
