def fmtAge(ms: float) -> str {
    s = Math.round((Date.now() - ms) / 1000);
    if (s < 60) {
        return f"{s}s";
    }
    m = Math.floor(s / 60);
    if (m < 60) {
        return f"{m}m";
    }
    return f"{Math.floor(m / 60)}h";
}

